"""mcpsmith is now toolsmelt. `import mcpsmith.X` gives the very module `toolsmelt.X`, so servers generated by
mcpsmith (which import `mcpsmith.runtime`) keep working on upgrade."""

import importlib
import importlib.abc
import importlib.util
import sys

from toolsmelt import __version__, getenv  # noqa: F401


class _Alias(importlib.abc.MetaPathFinder, importlib.abc.Loader):
    def find_spec(self, name, path=None, target=None):
        return importlib.util.spec_from_loader(name, self) if name.startswith("mcpsmith.") else None

    def create_module(self, spec):
        return importlib.import_module("toolsmelt" + spec.name[len("mcpsmith") :])  # the same module object

    def exec_module(self, module):
        pass  # already executed as toolsmelt.<name>


sys.meta_path.insert(0, _Alias())
__path__ = []  # a package, so `import mcpsmith.runtime` asks the finders above
